import type { Metadata } from "next";
import NextTopLoader from "nextjs-toploader";
import "~/style/global.css";
import "~/style/theme-button.css";
import { themeMetaInitScript } from "~/theme/ThemeMeta";
import { SITE_NAME, SITE_URL } from "~/utils/domain";
import { geist, geistMono, headlandOne, pollerOne, poppins } from "./font";
import Providers from "./providers";

export const dynamic = "force-static";
export const revalidate = false;

export const metadata: Metadata = {
  title: "Pinktra | A World of Knowledge",
  description:
    "Pinktra is a learning and digital products platform. Explore guides and tutorials across technology, science, finance, health, and more, discover practical tools, and get custom digital products built for you.",
  applicationName: SITE_NAME,
  authors: [{ name: "Sathish Kumar" }],
  metadataBase: new URL(SITE_URL),
  alternates: { canonical: "/" },
  keywords:
    "Pinktra, learning platform, tutorials, guides, knowledge domains, digital products, habit tracker, trading journal, web development services, app development, custom software",
  other: {
    google: "notranslate",
    "pinterest-rich-pin": "true",
  },
  appleWebApp: {
    capable: true,
    statusBarStyle: "default",
    title: SITE_NAME,
  },
  icons: {
    apple: "/apple-touch-icon.png",
    icon: [
      { url: "/favicon-32x32.png", sizes: "32x32", type: "image/png" },
      { url: "/favicon-16x16.png", sizes: "16x16", type: "image/png" },
    ],
  },
  manifest: "/site.webmanifest",
};

export const viewport = {
  width: "device-width",
  initialScale: 1,
  themeColor: "#f0b4d7",
  colorScheme: "light dark",
};

const websiteSchema = {
  "@context": "https://schema.org",
  "@type": "WebSite",
  name: SITE_NAME,
  url: SITE_URL,
  keywords:
    "Pinktra, learning platform, tutorials, guides, knowledge domains, digital products, web development services, app development, custom software",
};

const orgSchema = {
  "@context": "https://schema.org",
  "@type": "Organization",
  name: SITE_NAME,
  url: SITE_URL,
  logo: `${SITE_URL}/favicon-32x32.png`,
  contactPoint: {
    "@type": "ContactPoint",
    email: "sathish08032006@gmail.com",
    telephone: "+91-9566506832",
    contactType: "Customer Service",
  },
  address: {
    "@type": "PostalAddress",
    addressLocality: "Chennai",
    addressRegion: "TN",
    addressCountry: "IN",
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html
      lang="en"
      suppressHydrationWarning
      className={[
        poppins.variable,
        pollerOne.variable,
        headlandOne.variable,
        geist.variable,
        geistMono.variable,
      ].join(" ")}
    >
      <head>
        <meta httpEquiv="Content-Language" content="en,ta,hi" />
        <meta name="mobile-web-app-capable" content="yes" />
        <script
          async
          src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-4195505879971996"
          crossOrigin="anonymous"
        ></script>
        <script id="theme-meta-init" dangerouslySetInnerHTML={{ __html: themeMetaInitScript }} />
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(websiteSchema) }}
        />
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(orgSchema) }}
        />
      </head>
      <body>
        <NextTopLoader color="var(--accent-color)" showSpinner={false} />
        <Providers>{children}</Providers>
      </body>
    </html>
  );
}
